package com.paytrace.recovery; import jakarta.persistence.*; import java.time.Instant; import java.util.UUID; @Entity @Table(name="recovery_recommendations") public class RecoveryRecommendationEntity { @Id private UUID id; @Column(name="payment_id",nullable=false) private UUID paymentId; @Enumerated(EnumType.STRING) @Column(nullable=false) private RecoveryAction action; @Column(nullable=false) private String rationale; @Column(name="created_at",nullable=false) private Instant createdAt; protected RecoveryRecommendationEntity(){} public RecoveryRecommendationEntity(RecoveryRecommendation r){id=r.recommendationId();paymentId=r.paymentId();action=r.action();rationale=r.rationale();createdAt=r.createdAt();} public RecoveryRecommendation view(){return new RecoveryRecommendation(id,paymentId,action,rationale,createdAt);} }
